// Concatenates the kit's stylesheets (and their generated RTL copies) into one file per direction, so the
// first paint waits on one stylesheet instead of six. The kit's own files are never edited; rerun after
// any change in public/assets (and after scripts/build-rtl-kit.mjs).
//   node scripts/build-kit-bundle.mjs
import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { transform } from 'lightningcss'

const ROOT = new URL('../public/assets/', import.meta.url).pathname
// motion.css stays its own file: the kit's motion layer is linked by name (its checker looks for it)
const FILES = ['system.css', 'ui/cards.css', 'backgrounds/backgrounds.css', 'layout/layout.css', 'icons/icon.css']
for (const [dir, out] of [['', 'kit.bundle.css'], ['rtl/', 'kit.rtl.bundle.css']]) {
  const parts = []
  for (const f of FILES) parts.push(`/* ---- ${dir}${f} */\n` + (await readFile(join(ROOT, dir, f), 'utf8')))
  // the page's own CSS last, so it still overrides the kit
  parts.push(await readFile(new URL('../public/site/apex.css', import.meta.url), 'utf8'))
  // minified: the kit's sources carry long explanatory comments (253 KB raw -> about 28 KB gzipped)
  const { code } = transform({ filename: out, code: Buffer.from(parts.join('\n')), minify: true, targets: { safari: 16 << 16, chrome: 110 << 16, firefox: 115 << 16 } })
  await writeFile(join(ROOT, out), `/* generated by scripts/build-kit-bundle.mjs from the kit's own files: do not edit */\n${code}`)
  console.log(out)
}
